BEGIN;
CREATE SCHEMA folio;
REVOKE ALL ON SCHEMA folio FROM PUBLIC, anon, authenticated;
CREATE TABLE folio.users(id TEXT PRIMARY KEY,email TEXT UNIQUE,name TEXT NOT NULL,role TEXT NOT NULL);
CREATE TABLE folio.subjects(id TEXT PRIMARY KEY,title TEXT,description TEXT,theme TEXT,cover TEXT,visible BIGINT,pos BIGINT,version BIGINT DEFAULT 1);
CREATE TABLE folio.tasks(id TEXT PRIMARY KEY,sid TEXT REFERENCES folio.subjects(id) DEFERRABLE INITIALLY DEFERRED,body TEXT,published BIGINT,pos BIGINT,version BIGINT DEFAULT 1);
CREATE TABLE folio.files(id TEXT PRIMARY KEY,sid TEXT REFERENCES folio.subjects(id) DEFERRABLE INITIALLY DEFERRED,name TEXT,type TEXT,size BIGINT);
CREATE TABLE folio.quizzes(id TEXT PRIMARY KEY,sid TEXT REFERENCES folio.subjects(id) DEFERRABLE INITIALLY DEFERRED,author TEXT REFERENCES folio.users(id) DEFERRABLE INITIALLY DEFERRED,body TEXT,version BIGINT DEFAULT 1);
CREATE TABLE folio.shares(qid TEXT REFERENCES folio.quizzes(id) DEFERRABLE INITIALLY DEFERRED,sid TEXT REFERENCES folio.subjects(id) DEFERRABLE INITIALLY DEFERRED,PRIMARY KEY(qid,sid));
CREATE TABLE folio.runs(id TEXT PRIMARY KEY,pin TEXT,owner TEXT REFERENCES folio.users(id) DEFERRABLE INITIALLY DEFERRED,sid TEXT REFERENCES folio.subjects(id) DEFERRABLE INITIALLY DEFERRED,qid TEXT REFERENCES folio.quizzes(id) DEFERRABLE INITIALLY DEFERRED,task TEXT,request TEXT,body TEXT,phase TEXT,idx BIGINT,deadline BIGINT,remaining BIGINT,version BIGINT,started BIGINT,ended BIGINT,early BIGINT DEFAULT 0, volume REAL NOT NULL DEFAULT 1,UNIQUE(owner,request));
CREATE TABLE folio.players(id TEXT PRIMARY KEY,run TEXT REFERENCES folio.runs(id) DEFERRABLE INITIALLY DEFERRED,name TEXT,normalized TEXT,token TEXT UNIQUE,joined BIGINT,UNIQUE(run,normalized));
CREATE TABLE folio.answers(player TEXT REFERENCES folio.players(id) DEFERRABLE INITIALLY DEFERRED,idx BIGINT,value TEXT,points BIGINT,at BIGINT,PRIMARY KEY(player,idx));
CREATE TABLE folio.migrations(name TEXT PRIMARY KEY);
CREATE TABLE folio.player_avatars(player TEXT PRIMARY KEY REFERENCES folio.players(id) DEFERRABLE INITIALLY DEFERRED, avatar TEXT NOT NULL);
CREATE TABLE folio.areas(id TEXT PRIMARY KEY, sid TEXT NOT NULL REFERENCES folio.subjects(id) DEFERRABLE INITIALLY DEFERRED, title TEXT NOT NULL, icon TEXT NOT NULL, pos BIGINT NOT NULL, version BIGINT NOT NULL DEFAULT 1);
CREATE TABLE folio.task_areas(task TEXT PRIMARY KEY REFERENCES folio.tasks(id) DEFERRABLE INITIALLY DEFERRED, area TEXT NOT NULL REFERENCES folio.areas(id) DEFERRABLE INITIALLY DEFERRED, created_order BIGINT NOT NULL UNIQUE);
CREATE TABLE folio.subject_icons(sid TEXT PRIMARY KEY REFERENCES folio.subjects(id) DEFERRABLE INITIALLY DEFERRED, icon TEXT NOT NULL);
CREATE TABLE folio.feedback_forms(id TEXT PRIMARY KEY, sid TEXT NOT NULL REFERENCES folio.subjects(id) DEFERRABLE INITIALLY DEFERRED, owner TEXT NOT NULL REFERENCES folio.users(id) DEFERRABLE INITIALLY DEFERRED, title TEXT NOT NULL, questions TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft', share TEXT NOT NULL UNIQUE, responses BIGINT NOT NULL DEFAULT 0, version BIGINT NOT NULL DEFAULT 1, created BIGINT NOT NULL, closed_at BIGINT, comments_removed BIGINT NOT NULL DEFAULT 0);
CREATE TABLE folio.feedback_counts(form TEXT NOT NULL REFERENCES folio.feedback_forms(id) DEFERRABLE INITIALLY DEFERRED, question TEXT NOT NULL, answer TEXT NOT NULL, n BIGINT NOT NULL, PRIMARY KEY(form,question,answer));
CREATE TABLE folio.feedback_receipts(form TEXT NOT NULL REFERENCES folio.feedback_forms(id) DEFERRABLE INITIALLY DEFERRED, digest TEXT NOT NULL, PRIMARY KEY(form,digest));
CREATE TABLE folio.removed_subjects(id TEXT PRIMARY KEY REFERENCES folio.subjects(id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE folio.removed_run_sources(run TEXT PRIMARY KEY REFERENCES folio.runs(id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE folio.retention_policy(id BIGINT PRIMARY KEY, games BIGINT, comments BIGINT, version BIGINT NOT NULL);
CREATE UNIQUE INDEX active_pin ON folio.runs(pin) WHERE ended IS NULL;
CREATE INDEX tasks_by_area ON folio.task_areas(area,created_order);
CREATE UNIQUE INDEX single_folio_admin ON folio.users (role) WHERE role='admin';
INSERT INTO folio.users VALUES('folio-admin','mrindos@stavebkaji.cz','Matěj Rindoš','admin');
CREATE TABLE folio.clock(id boolean PRIMARY KEY CHECK(id), rev bigint NOT NULL);
INSERT INTO folio.clock VALUES(true,0);
ALTER TABLE folio.users ENABLE ROW LEVEL SECURITY; ALTER TABLE folio.subjects ENABLE ROW LEVEL SECURITY;
ALTER TABLE folio.tasks ENABLE ROW LEVEL SECURITY; ALTER TABLE folio.files ENABLE ROW LEVEL SECURITY;
ALTER TABLE folio.quizzes ENABLE ROW LEVEL SECURITY; ALTER TABLE folio.shares ENABLE ROW LEVEL SECURITY;
ALTER TABLE folio.runs ENABLE ROW LEVEL SECURITY; ALTER TABLE folio.players ENABLE ROW LEVEL SECURITY;
ALTER TABLE folio.answers ENABLE ROW LEVEL SECURITY; ALTER TABLE folio.migrations ENABLE ROW LEVEL SECURITY;
ALTER TABLE folio.player_avatars ENABLE ROW LEVEL SECURITY; ALTER TABLE folio.areas ENABLE ROW LEVEL SECURITY;
ALTER TABLE folio.task_areas ENABLE ROW LEVEL SECURITY; ALTER TABLE folio.subject_icons ENABLE ROW LEVEL SECURITY;
ALTER TABLE folio.feedback_forms ENABLE ROW LEVEL SECURITY; ALTER TABLE folio.feedback_counts ENABLE ROW LEVEL SECURITY;
ALTER TABLE folio.feedback_receipts ENABLE ROW LEVEL SECURITY; ALTER TABLE folio.removed_subjects ENABLE ROW LEVEL SECURITY;
ALTER TABLE folio.removed_run_sources ENABLE ROW LEVEL SECURITY; ALTER TABLE folio.retention_policy ENABLE ROW LEVEL SECURITY;
ALTER TABLE folio.clock ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.folio_read(known bigint) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog AS $$
 SELECT CASE WHEN rev=known THEN jsonb_build_object('rev',rev) ELSE jsonb_build_object('rev',rev,'tables', jsonb_build_object('users',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) FROM folio.users t)) || jsonb_build_object('subjects',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) FROM folio.subjects t)) || jsonb_build_object('tasks',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) FROM folio.tasks t)) || jsonb_build_object('files',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) FROM folio.files t)) || jsonb_build_object('quizzes',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) FROM folio.quizzes t)) || jsonb_build_object('shares',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) FROM folio.shares t)) || jsonb_build_object('runs',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) FROM folio.runs t)) || jsonb_build_object('players',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) FROM folio.players t)) || jsonb_build_object('answers',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) FROM folio.answers t)) || jsonb_build_object('migrations',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) FROM folio.migrations t)) || jsonb_build_object('player_avatars',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) FROM folio.player_avatars t)) || jsonb_build_object('areas',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) FROM folio.areas t)) || jsonb_build_object('task_areas',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) FROM folio.task_areas t)) || jsonb_build_object('subject_icons',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) FROM folio.subject_icons t)) || jsonb_build_object('feedback_forms',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) FROM folio.feedback_forms t)) || jsonb_build_object('feedback_counts',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) FROM folio.feedback_counts t)) || jsonb_build_object('feedback_receipts',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) FROM folio.feedback_receipts t)) || jsonb_build_object('removed_subjects',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) FROM folio.removed_subjects t)) || jsonb_build_object('removed_run_sources',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) FROM folio.removed_run_sources t)) || jsonb_build_object('retention_policy',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) FROM folio.retention_policy t))) END FROM folio.clock WHERE id;
$$;
CREATE FUNCTION public.folio_commit(expected bigint, changes jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
BEGIN
 UPDATE folio.clock SET rev=rev+1 WHERE id AND rev=expected;
 IF NOT FOUND THEN RETURN false; END IF;
 IF changes ? 'retention_policy' THEN DELETE FROM folio.retention_policy t USING jsonb_populate_recordset(NULL::folio.retention_policy, changes->'retention_policy'->'del') x WHERE t."id"=x."id"; END IF;
 IF changes ? 'removed_run_sources' THEN DELETE FROM folio.removed_run_sources t USING jsonb_populate_recordset(NULL::folio.removed_run_sources, changes->'removed_run_sources'->'del') x WHERE t."run"=x."run"; END IF;
 IF changes ? 'removed_subjects' THEN DELETE FROM folio.removed_subjects t USING jsonb_populate_recordset(NULL::folio.removed_subjects, changes->'removed_subjects'->'del') x WHERE t."id"=x."id"; END IF;
 IF changes ? 'feedback_receipts' THEN DELETE FROM folio.feedback_receipts t USING jsonb_populate_recordset(NULL::folio.feedback_receipts, changes->'feedback_receipts'->'del') x WHERE t."form"=x."form" AND t."digest"=x."digest"; END IF;
 IF changes ? 'feedback_counts' THEN DELETE FROM folio.feedback_counts t USING jsonb_populate_recordset(NULL::folio.feedback_counts, changes->'feedback_counts'->'del') x WHERE t."form"=x."form" AND t."question"=x."question" AND t."answer"=x."answer"; END IF;
 IF changes ? 'feedback_forms' THEN DELETE FROM folio.feedback_forms t USING jsonb_populate_recordset(NULL::folio.feedback_forms, changes->'feedback_forms'->'del') x WHERE t."id"=x."id"; END IF;
 IF changes ? 'subject_icons' THEN DELETE FROM folio.subject_icons t USING jsonb_populate_recordset(NULL::folio.subject_icons, changes->'subject_icons'->'del') x WHERE t."sid"=x."sid"; END IF;
 IF changes ? 'task_areas' THEN DELETE FROM folio.task_areas t USING jsonb_populate_recordset(NULL::folio.task_areas, changes->'task_areas'->'del') x WHERE t."task"=x."task"; END IF;
 IF changes ? 'areas' THEN DELETE FROM folio.areas t USING jsonb_populate_recordset(NULL::folio.areas, changes->'areas'->'del') x WHERE t."id"=x."id"; END IF;
 IF changes ? 'player_avatars' THEN DELETE FROM folio.player_avatars t USING jsonb_populate_recordset(NULL::folio.player_avatars, changes->'player_avatars'->'del') x WHERE t."player"=x."player"; END IF;
 IF changes ? 'migrations' THEN DELETE FROM folio.migrations t USING jsonb_populate_recordset(NULL::folio.migrations, changes->'migrations'->'del') x WHERE t."name"=x."name"; END IF;
 IF changes ? 'answers' THEN DELETE FROM folio.answers t USING jsonb_populate_recordset(NULL::folio.answers, changes->'answers'->'del') x WHERE t."player"=x."player" AND t."idx"=x."idx"; END IF;
 IF changes ? 'players' THEN DELETE FROM folio.players t USING jsonb_populate_recordset(NULL::folio.players, changes->'players'->'del') x WHERE t."id"=x."id"; END IF;
 IF changes ? 'runs' THEN DELETE FROM folio.runs t USING jsonb_populate_recordset(NULL::folio.runs, changes->'runs'->'del') x WHERE t."id"=x."id"; END IF;
 IF changes ? 'shares' THEN DELETE FROM folio.shares t USING jsonb_populate_recordset(NULL::folio.shares, changes->'shares'->'del') x WHERE t."qid"=x."qid" AND t."sid"=x."sid"; END IF;
 IF changes ? 'quizzes' THEN DELETE FROM folio.quizzes t USING jsonb_populate_recordset(NULL::folio.quizzes, changes->'quizzes'->'del') x WHERE t."id"=x."id"; END IF;
 IF changes ? 'files' THEN DELETE FROM folio.files t USING jsonb_populate_recordset(NULL::folio.files, changes->'files'->'del') x WHERE t."id"=x."id"; END IF;
 IF changes ? 'tasks' THEN DELETE FROM folio.tasks t USING jsonb_populate_recordset(NULL::folio.tasks, changes->'tasks'->'del') x WHERE t."id"=x."id"; END IF;
 IF changes ? 'subjects' THEN DELETE FROM folio.subjects t USING jsonb_populate_recordset(NULL::folio.subjects, changes->'subjects'->'del') x WHERE t."id"=x."id"; END IF;
 IF changes ? 'users' THEN DELETE FROM folio.users t USING jsonb_populate_recordset(NULL::folio.users, changes->'users'->'del') x WHERE t."id"=x."id"; END IF;
 IF changes ? 'users' THEN INSERT INTO folio.users SELECT * FROM jsonb_populate_recordset(NULL::folio.users, changes->'users'->'put') ON CONFLICT (id) DO UPDATE SET "email"=EXCLUDED."email", "name"=EXCLUDED."name", "role"=EXCLUDED."role"; END IF;
 IF changes ? 'subjects' THEN INSERT INTO folio.subjects SELECT * FROM jsonb_populate_recordset(NULL::folio.subjects, changes->'subjects'->'put') ON CONFLICT (id) DO UPDATE SET "title"=EXCLUDED."title", "description"=EXCLUDED."description", "theme"=EXCLUDED."theme", "cover"=EXCLUDED."cover", "visible"=EXCLUDED."visible", "pos"=EXCLUDED."pos", "version"=EXCLUDED."version"; END IF;
 IF changes ? 'tasks' THEN INSERT INTO folio.tasks SELECT * FROM jsonb_populate_recordset(NULL::folio.tasks, changes->'tasks'->'put') ON CONFLICT (id) DO UPDATE SET "sid"=EXCLUDED."sid", "body"=EXCLUDED."body", "published"=EXCLUDED."published", "pos"=EXCLUDED."pos", "version"=EXCLUDED."version"; END IF;
 IF changes ? 'files' THEN INSERT INTO folio.files SELECT * FROM jsonb_populate_recordset(NULL::folio.files, changes->'files'->'put') ON CONFLICT (id) DO UPDATE SET "sid"=EXCLUDED."sid", "name"=EXCLUDED."name", "type"=EXCLUDED."type", "size"=EXCLUDED."size"; END IF;
 IF changes ? 'quizzes' THEN INSERT INTO folio.quizzes SELECT * FROM jsonb_populate_recordset(NULL::folio.quizzes, changes->'quizzes'->'put') ON CONFLICT (id) DO UPDATE SET "sid"=EXCLUDED."sid", "author"=EXCLUDED."author", "body"=EXCLUDED."body", "version"=EXCLUDED."version"; END IF;
 IF changes ? 'shares' THEN INSERT INTO folio.shares SELECT * FROM jsonb_populate_recordset(NULL::folio.shares, changes->'shares'->'put') ON CONFLICT (qid,sid) DO NOTHING; END IF;
 IF changes ? 'runs' THEN INSERT INTO folio.runs SELECT * FROM jsonb_populate_recordset(NULL::folio.runs, changes->'runs'->'put') ON CONFLICT (id) DO UPDATE SET "pin"=EXCLUDED."pin", "owner"=EXCLUDED."owner", "sid"=EXCLUDED."sid", "qid"=EXCLUDED."qid", "task"=EXCLUDED."task", "request"=EXCLUDED."request", "body"=EXCLUDED."body", "phase"=EXCLUDED."phase", "idx"=EXCLUDED."idx", "deadline"=EXCLUDED."deadline", "remaining"=EXCLUDED."remaining", "version"=EXCLUDED."version", "started"=EXCLUDED."started", "ended"=EXCLUDED."ended", "early"=EXCLUDED."early", "volume"=EXCLUDED."volume"; END IF;
 IF changes ? 'players' THEN INSERT INTO folio.players SELECT * FROM jsonb_populate_recordset(NULL::folio.players, changes->'players'->'put') ON CONFLICT (id) DO UPDATE SET "run"=EXCLUDED."run", "name"=EXCLUDED."name", "normalized"=EXCLUDED."normalized", "token"=EXCLUDED."token", "joined"=EXCLUDED."joined"; END IF;
 IF changes ? 'answers' THEN INSERT INTO folio.answers SELECT * FROM jsonb_populate_recordset(NULL::folio.answers, changes->'answers'->'put') ON CONFLICT (player,idx) DO UPDATE SET "value"=EXCLUDED."value", "points"=EXCLUDED."points", "at"=EXCLUDED."at"; END IF;
 IF changes ? 'migrations' THEN INSERT INTO folio.migrations SELECT * FROM jsonb_populate_recordset(NULL::folio.migrations, changes->'migrations'->'put') ON CONFLICT (name) DO NOTHING; END IF;
 IF changes ? 'player_avatars' THEN INSERT INTO folio.player_avatars SELECT * FROM jsonb_populate_recordset(NULL::folio.player_avatars, changes->'player_avatars'->'put') ON CONFLICT (player) DO UPDATE SET "avatar"=EXCLUDED."avatar"; END IF;
 IF changes ? 'areas' THEN INSERT INTO folio.areas SELECT * FROM jsonb_populate_recordset(NULL::folio.areas, changes->'areas'->'put') ON CONFLICT (id) DO UPDATE SET "sid"=EXCLUDED."sid", "title"=EXCLUDED."title", "icon"=EXCLUDED."icon", "pos"=EXCLUDED."pos", "version"=EXCLUDED."version"; END IF;
 IF changes ? 'task_areas' THEN INSERT INTO folio.task_areas SELECT * FROM jsonb_populate_recordset(NULL::folio.task_areas, changes->'task_areas'->'put') ON CONFLICT (task) DO UPDATE SET "area"=EXCLUDED."area", "created_order"=EXCLUDED."created_order"; END IF;
 IF changes ? 'subject_icons' THEN INSERT INTO folio.subject_icons SELECT * FROM jsonb_populate_recordset(NULL::folio.subject_icons, changes->'subject_icons'->'put') ON CONFLICT (sid) DO UPDATE SET "icon"=EXCLUDED."icon"; END IF;
 IF changes ? 'feedback_forms' THEN INSERT INTO folio.feedback_forms SELECT * FROM jsonb_populate_recordset(NULL::folio.feedback_forms, changes->'feedback_forms'->'put') ON CONFLICT (id) DO UPDATE SET "sid"=EXCLUDED."sid", "owner"=EXCLUDED."owner", "title"=EXCLUDED."title", "questions"=EXCLUDED."questions", "status"=EXCLUDED."status", "share"=EXCLUDED."share", "responses"=EXCLUDED."responses", "version"=EXCLUDED."version", "created"=EXCLUDED."created", "closed_at"=EXCLUDED."closed_at", "comments_removed"=EXCLUDED."comments_removed"; END IF;
 IF changes ? 'feedback_counts' THEN INSERT INTO folio.feedback_counts SELECT * FROM jsonb_populate_recordset(NULL::folio.feedback_counts, changes->'feedback_counts'->'put') ON CONFLICT (form,question,answer) DO UPDATE SET "n"=EXCLUDED."n"; END IF;
 IF changes ? 'feedback_receipts' THEN INSERT INTO folio.feedback_receipts SELECT * FROM jsonb_populate_recordset(NULL::folio.feedback_receipts, changes->'feedback_receipts'->'put') ON CONFLICT (form,digest) DO NOTHING; END IF;
 IF changes ? 'removed_subjects' THEN INSERT INTO folio.removed_subjects SELECT * FROM jsonb_populate_recordset(NULL::folio.removed_subjects, changes->'removed_subjects'->'put') ON CONFLICT (id) DO NOTHING; END IF;
 IF changes ? 'removed_run_sources' THEN INSERT INTO folio.removed_run_sources SELECT * FROM jsonb_populate_recordset(NULL::folio.removed_run_sources, changes->'removed_run_sources'->'put') ON CONFLICT (run) DO NOTHING; END IF;
 IF changes ? 'retention_policy' THEN INSERT INTO folio.retention_policy SELECT * FROM jsonb_populate_recordset(NULL::folio.retention_policy, changes->'retention_policy'->'put') ON CONFLICT (id) DO UPDATE SET "games"=EXCLUDED."games", "comments"=EXCLUDED."comments", "version"=EXCLUDED."version"; END IF;
 RETURN true; END; $$;
REVOKE ALL ON FUNCTION public.folio_read(bigint), public.folio_commit(bigint,jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.folio_read(bigint), public.folio_commit(bigint,jsonb) TO service_role;
INSERT INTO storage.buckets(id,name,public,file_size_limit) VALUES('folio-files','folio-files',false,26214400);
COMMIT;
